  console.log(this);
}

pokazThis(); // undefined (w module ES / trybie strict)
            // lub globalny obiekt window w "luznym" skrypcie przegladarki

function podajNazwe() {
  return this.nazwa;
}

const sklepA = { nazwa: "Kwiaciarnia u Ani", podajNazwe };
const sklepB = { nazwa: "Piekarnia Complex", podajNazwe };

console.log(sklepA.podajNazwe()); // "Kwiaciarnia u Ani"
console.log(sklepB.podajNazwe()); // "Piekarnia Complex" - TA SAMA funkcja, inny this!

const uzytkownik = { imie: "Kasia", pokazImie() { return this.imie; } };
const funkcja = uzytkownik.pokazImie;

// BLEDNE zalozenie: "this zawsze bedzie uzytkownik, bo TU zostalo zdefiniowane"
console.log(funkcja()); // Blad LUB undefined - this NIE jest juz uzytkownik!

